import React from "react";
import "./Card.css";

interface CardProps {
  children: React.ReactNode;
  className?: string;
  onClick: (name: string) => void;
}

const Card: React.FC<CardProps> = ({ children, className, onClick }) => {
  return (
    <div className={`card ${className}`} onClick={() => onClick}>
      {children}
    </div>
  );
};

export default Card;
